import{_ as a,o as t,c as o,a2 as n}from"./chunks/framework.D4CBuebE.js";const m=JSON.parse('{"title":"Terms of Service","description":"The terms for using Tackora, the website and the runner.","frontmatter":{"title":"Terms of Service","description":"The terms for using Tackora, the website and the runner.","aside":false},"headers":[],"relativePath":"terms.md","filePath":"terms.md","lastUpdated":1790952380000}'),r={name:"terms.md"};function s(i,e,h,c,l,u){return t(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="terms-of-service" tabindex="-1">Terms of Service <a class="header-anchor" href="#terms-of-service" aria-label="Permalink to &quot;Terms of Service&quot;">​</a></h1><p><em>Last updated 1 October 2026</em></p><p>These terms are an agreement between you and Cyberia AI Studio, Tunisia, the maker of Tackora (&quot;we&quot;, &quot;us&quot;), for using the Tackora website, its web app and the Tackora runner (together, &quot;the Service&quot;). By creating an account or using the Service you accept them. If you use it for an organization, you accept them on its behalf and confirm you may do so.</p><h2 id="_1-what-the-service-is" tabindex="-1">1. What the Service is <a class="header-anchor" href="#_1-what-the-service-is" aria-label="Permalink to &quot;1. What the Service is&quot;">​</a></h2><p>Tackora is a board for coding agents. Tickets, conversations and the logs of each run are kept on our servers. The agents themselves run on computers you connect with the runner (&quot;your machines&quot;), in your repositories, with your own accounts and keys for each agent. We never run your code and never clone or store your repositories.</p><h2 id="_2-accounts" tabindex="-1">2. Accounts <a class="header-anchor" href="#_2-accounts" aria-label="Permalink to &quot;2. Accounts&quot;">​</a></h2><p>You sign in with a third-party account such as GitHub. Keep it secure: you are responsible for everything done with your Tackora account and the runners you connect to it. Tell us right away if you think someone else has access. You must be old enough to agree to these terms where you live, and at least 16.</p><h2 id="_3-organizations-and-members" tabindex="-1">3. Organizations and members <a class="header-anchor" href="#_3-organizations-and-members" aria-label="Permalink to &quot;3. Organizations and members&quot;">​</a></h2><p>An organization&#39;s admins decide who is a member and what members may do. Members see the organization&#39;s board, answer its agents and may connect machines. Admins are responsible for their members&#39; use of the organization.</p><h2 id="_4-your-machines-and-your-agents" tabindex="-1">4. Your machines and your agents <a class="header-anchor" href="#_4-your-machines-and-your-agents" aria-label="Permalink to &quot;4. Your machines and your agents&quot;">​</a></h2><p>The runner starts agents on your machines with the permissions you choose (for example &quot;Ask first&quot; or &quot;Unattended&quot;). You are responsible for:</p><ul><li>what those agents do on your machines and in your repositories, including the commands they run and the changes they make, whether you approved each one or chose a policy that doesn&#39;t ask;</li><li>the credentials available on your machines, and following the terms of each agent&#39;s provider (Anthropic, OpenAI, Google, GitHub and others) for your use of their agents;</li><li>reviewing the changes and pull requests agents produce before you merge or deploy them.</li></ul><p>Agents make mistakes. Use policies, approvals and review that match the risk of each repository.</p><h2 id="_5-your-content" tabindex="-1">5. Your content <a class="header-anchor" href="#_5-your-content" aria-label="Permalink to &quot;5. Your content&quot;">​</a></h2><p>You keep all rights to what you put into the Service: tickets, descriptions, conversations, attachments, notes and the logs your runners send (&quot;your content&quot;). You give us the permission we need to store, process and show your content to you and your organization in order to run the Service, and nothing more. We do not use your content to train models and do not sell it.</p><h2 id="_6-acceptable-use" tabindex="-1">6. Acceptable use <a class="header-anchor" href="#_6-acceptable-use" aria-label="Permalink to &quot;6. Acceptable use&quot;">​</a></h2><p>Don&#39;t use the Service to break the law, to harm others, to attack or probe systems you don&#39;t own or aren&#39;t allowed to test, to send spam, or to get around these terms or the Service&#39;s limits. Don&#39;t interfere with the Service or try to access other organizations&#39; data. We may suspend accounts that do.</p><h2 id="_7-plans-and-payment" tabindex="-1">7. Plans and payment <a class="header-anchor" href="#_7-plans-and-payment" aria-label="Permalink to &quot;7. Plans and payment&quot;">​</a></h2><p>The Free plan, and the limits of each plan (people, machines, repositories), are as shown on our pricing page. The Pro and Team plans are billed monthly or yearly at the price shown on our website when you subscribe, plus any taxes. Subscriptions renew each period until you cancel; cancelling stops the next renewal, and the plan runs to the end of the period you&#39;ve paid for. The Team trial lasts 14 days, needs no payment details, and is available once per person. We&#39;ll tell you at least 30 days before a price change applies to you. Payments are handled by Polar, our merchant of record, which sells the subscription to you, collects any sales tax or VAT and sends the invoices; we don&#39;t see or store card numbers.</p><h2 id="_8-availability-and-changes" tabindex="-1">8. Availability and changes <a class="header-anchor" href="#_8-availability-and-changes" aria-label="Permalink to &quot;8. Availability and changes&quot;">​</a></h2><p>We work to keep the Service running and your data safe, but we don&#39;t promise it will be uninterrupted or free of errors. We may change, add or remove features. If we stop offering the Service, we&#39;ll give you at least 60 days&#39; notice and a way to export your content.</p><h2 id="_9-ending-your-use" tabindex="-1">9. Ending your use <a class="header-anchor" href="#_9-ending-your-use" aria-label="Permalink to &quot;9. Ending your use&quot;">​</a></h2><p>You can stop using the Service and delete your organization at any time. We may suspend or end your access if you break these terms, after warning you when that&#39;s reasonable. When an account or organization is deleted, its content is deleted from our systems within 30 days, apart from records we must keep by law.</p><h2 id="_10-disclaimers" tabindex="-1">10. Disclaimers <a class="header-anchor" href="#_10-disclaimers" aria-label="Permalink to &quot;10. Disclaimers&quot;">​</a></h2><p>The Service is provided &quot;as is&quot;. To the extent the law allows, we disclaim all warranties, including fitness for a particular purpose and non-infringement. Code and changes produced by agents come from the agents and their providers, not from us.</p><h2 id="_11-limitation-of-liability" tabindex="-1">11. Limitation of liability <a class="header-anchor" href="#_11-limitation-of-liability" aria-label="Permalink to &quot;11. Limitation of liability&quot;">​</a></h2><p>To the extent the law allows, we are not liable for indirect, incidental, special or consequential damages, or for lost profits, data or code, including anything an agent did on your machines. Our total liability for any claim about the Service is limited to the amount you paid us in the 12 months before the claim.</p><h2 id="_12-changes-to-these-terms" tabindex="-1">12. Changes to these terms <a class="header-anchor" href="#_12-changes-to-these-terms" aria-label="Permalink to &quot;12. Changes to these terms&quot;">​</a></h2><p>If we change these terms in a way that matters, we&#39;ll post the new version here and tell account holders by email at least 30 days before it applies. Continuing to use the Service after that means you accept the new terms.</p><h2 id="_13-governing-law" tabindex="-1">13. Governing law <a class="header-anchor" href="#_13-governing-law" aria-label="Permalink to &quot;13. Governing law&quot;">​</a></h2><p>These terms are governed by the laws of Tunisia. Disputes go to the competent courts of Tunisia, unless the law of the country you live in gives you the right to bring them there.</p><h2 id="_14-contact" tabindex="-1">14. Contact <a class="header-anchor" href="#_14-contact" aria-label="Permalink to &quot;14. Contact&quot;">​</a></h2><p>Cyberia AI Studio, Tunisia — <a href="mailto:anas.bassoumi@gmail.com" target="_blank" rel="noreferrer">anas.bassoumi@gmail.com</a>.</p>',33)])])}const p=a(r,[["render",s]]);export{m as __pageData,p as default};
